),
candidates AS (
  SELECT j.id, a.project_id
    FROM jobs j
    JOIN arc a ON a.num = COALESCE(NULLIF(j.external_ref, ''), 'JB' || LPAD(j.job_number::text, 5, '0'))
   WHERE j.arcsite_project_id IS NULL
),
safe AS (
  SELECT c.id, c.project_id
    FROM candidates c
   WHERE (SELECT COUNT(*) FROM candidates c2 WHERE c2.project_id = c.project_id) = 1
     AND NOT EXISTS (SELECT 1 FROM jobs j2 WHERE j2.arcsite_project_id = c.project_id)
)
UPDATE jobs j
   SET arcsite_project_id = s.project_id
  FROM safe s
 WHERE j.id = s.id;
